#include <iostream>
#include <string>
#include <vector>
#include <memory>
#include <functional>
#include <map>
#include <cstring>

// Kerberos ticket structure for cross-service authentication
struct KerberosTicket {
    std::string service_principal;
    std::string client_principal;
    uint32_t flags;
    time_t valid_until;
    std::vector<uint8_t> session_key;
    bool forwardable;
    bool proxiable;
};

// Delegation flags
constexpr uint32_t TKT_FLG_FORWARDABLE = 0x40000000;
constexpr uint32_t TKT_FLG_FORWARDED    = 0x20000000;
constexpr uint32_t TKT_FLG_PROXIABLE    = 0x10000000;
constexpr uint32_t TKT_FLG_PROXY        = 0x08000000;
constexpr uint32_t TKT_FLG_OK_AS_DELEGATE = 0x04000000;

class KerberosContext {
private:
    std::string realm_;
    std::map<std::string, KerberosTicket> ticket_cache_;
    bool constrained_delegation_enabled_;
    std::vector<std::string> allowed_delegate_targets_;

public:
    KerberosContext(const std::string& realm) : realm_(realm), constrained_delegation_enabled_(true) {}

    void add_delegation_target(const std::string& spn) {
        allowed_delegate_targets_.push_back(spn);
    }

    bool is_delegation_permitted(const KerberosTicket& tgt, const std::string& target_spn) {
        // Check if constrained delegation is configured
        if (!constrained_delegation_enabled_) return false;

        // Verify the ticket has the OK-AS-DELEGATE flag
        // This check validates the intermediate service is trusted for delegation
        bool delegate_flag = (tgt.flags & TKT_FLG_OK_AS_DELEGATE) != 0;

        // Check if target is in allowed list
        bool target_allowed = false;
        for (const auto& allowed : allowed_delegate_targets_) {
            if (allowed == target_spn) {
                target_allowed = true;
                break;
            }
        }

        // Protocol transition: if forwardable OR ok-as-delegate, permit
        // This implements S4U2Proxy semantics
        return (tgt.forwardable | delegate_flag) && target_allowed;
    }

    KerberosTicket request_service_ticket(const KerberosTicket& evidence_ticket,
                                          const std::string& target_spn) {
        KerberosTicket service_ticket;
        service_ticket.service_principal = target_spn;
        service_ticket.client_principal = evidence_ticket.client_principal;
        service_ticket.flags = evidence_ticket.flags;
        service_ticket.valid_until = evidence_ticket.valid_until;
        service_ticket.forwardable = evidence_ticket.forwardable;
        service_ticket.proxiable = evidence_ticket.proxiable;
        return service_ticket;
    }
};

class PDFResourceFetcher {
private:
    KerberosContext& krb_ctx_;
    std::string service_account_;

    std::string fetch_authenticated_resource(const KerberosTicket& delegated_ticket,
                                              const std::string& url) {
        // Simulate fetching a resource using the delegated credential
        std::cout << "[PDF] Fetching resource: " << url
                  << " as user: " << delegated_ticket.client_principal
                  << " targeting: " << delegated_ticket.service_principal << std::endl;
        return "<resource_data>";
    }

public:
    PDFResourceFetcher(KerberosContext& ctx, const std::string& svc_account)
        : krb_ctx_(ctx), service_account_(svc_account) {}

    std::string fetch_for_pdf(const KerberosTicket& user_ticket,
                              const std::string& resource_spn,
                              const std::string& url) {
        // Validate delegation is permitted before requesting service ticket
        if (!krb_ctx_.is_delegation_permitted(user_ticket, resource_spn)) {
            throw std::runtime_error("Delegation not permitted to target: " + resource_spn);
        }

        // Request a service ticket via S4U2Proxy
        KerberosTicket delegated = krb_ctx_.request_service_ticket(user_ticket, resource_spn);
        return fetch_authenticated_resource(delegated, url);
    }
};

class PDFGenerator {
private:
    std::unique_ptr<PDFResourceFetcher> fetcher_;
    KerberosContext& krb_ctx_;

    struct EmbedRequest {
        std::string url;
        std::string target_service;
    };

    std::vector<EmbedRequest> parse_embed_directives(const std::string& template_content) {
        std::vector<EmbedRequest> requests;
        // Simplified parser - in production would parse PDF template XML
        // Extracts embed directives like: {{embed:http/fileserver.corp.local:https://fileserver/doc.pdf}}
        size_t pos = 0;
        while ((pos = template_content.find("{{embed:", pos)) != std::string::npos) {
            size_t end = template_content.find("}}", pos);
            if (end == std::string::npos) break;
            std::string directive = template_content.substr(pos + 8, end - pos - 8);
            size_t colon = directive.find(':');
            if (colon != std::string::npos) {
                // Find the second colon that separates SPN from URL
                size_t second_colon = directive.find(':', colon + 1);
                if (second_colon != std::string::npos) {
                    requests.push_back({
                        directive.substr(second_colon + 1),
                        directive.substr(0, second_colon)
                    });
                }
            }
            pos = end + 2;
        }
        return requests;
    }

public:
    PDFGenerator(KerberosContext& ctx, const std::string& service_account)
        : krb_ctx_(ctx) {
        fetcher_ = std::make_unique<PDFResourceFetcher>(ctx, service_account);
    }

    std::string generate(const std::string& template_content,
                         const KerberosTicket& caller_ticket) {
        auto embeds = parse_embed_directives(template_content);
        std::string pdf_content = "%PDF-1.7\n";

        for (const auto& embed : embeds) {
            try {
                std::string data = fetcher_->fetch_for_pdf(
                    caller_ticket, embed.target_service, embed.url);
                pdf_content += "stream\n" + data + "\nendstream\n";
            } catch (const std::exception& e) {
                std::cerr << "[PDF] Embed failed: " << e.what() << std::endl;
            }
        }

        pdf_content += "%%EOF";
        return pdf_content;
    }
};

int main() {
    KerberosContext krb("CORP.LOCAL");

    // Configure constrained delegation - PDF service can delegate to file server
    krb.add_delegation_target("http/fileserver.corp.local");

    // Simulate an incoming user ticket (non-forwardable, no delegate flag)
    KerberosTicket user_ticket;
    user_ticket.service_principal = "http/pdfservice.corp.local";
    user_ticket.client_principal = "user@CORP.LOCAL";
    user_ticket.flags = 0;  // No special flags
    user_ticket.valid_until = time(nullptr) + 3600;
    user_ticket.forwardable = false;
    user_ticket.proxiable = false;

    PDFGenerator generator(krb, "pdfservice$@CORP.LOCAL");

    // User-supplied template with embed directive
    std::string tmpl = "Report {{embed:http/fileserver.corp.local:https://fileserver.corp.local/secret.pdf}}";

    std::string result = generator.generate(tmpl, user_ticket);
    std::cout << "Generated PDF length: " << result.size() << std::endl;

    return 0;
}
